fn helper_lonik_body(ctx: &Ctx, args: Vec<Val>) -> Result<Val, Stop> {
    ctx.call(Function::Emotion, vec![ctx.constant("ET_BEST")?])?;
    ctx.lines_as("Lonik", args!["Tah dah! Here I am!"])?;
    ctx.next()?;
    ctx.lines_as("Lonik", args!["You are curious if there is anyone inside or not, aren't you?"])?;
    ctx.next()?;
    ctx.lines_as("Lonik", args!["My answer is...", "............."])?;
    if ctx.call(Function::GetMapUsers, vec![Val::from("force_1-2")])?.is_true() {
        ctx.call(Function::Emotion, vec![ctx.constant("ET_O")?])?;
        ctx.lines(args!["Yes!", "There is someone inside."])?;
        ctx.next()?;
        ctx.lines_as("Lonik", args!["You'd better wait a little bit longer!"])?;
    } else {
        ctx.call(Function::Emotion, vec![ctx.constant("ET_X")?])?;
        ctx.lines(args!["No!", "Go for it, good luck!"])?;
    }
    ctx.close_window()?;
    return Err(Stop::End);
}

