fn picture_manager_arena_body(ctx: &Ctx, args: Vec<Val>) -> Result<Val, Stop> {
    let mut l_i = Val::from(0);
    l_i = shared::other_gm_npcs::f_gm_npc(ctx, vec![Val::from(1357), Val::from(0)])?;
    if l_i.clone() == -1 {
        ctx.lines_as("Picture Manager", args!["Command has been canceled."])?;
        ctx.close_window()?;
        return Err(Stop::End);
    } else {
        if l_i.clone() == 0 {
            ctx.lines_as("Picture Manager", args!["Password is incorrect."])?;
            ctx.close_window()?;
            return Err(Stop::End);
        } else {
            ctx.lines_as(
                "Picture Manager",
                args!["Would you like to reset Picture Reward variable to 0?"],
            )?;
            ctx.next()?;
            'b1: {
                let subject1 = Val::from(runtime::select_values(ctx, &[Val::from("Cancel:Yes")])?);
                let mut matched1 = false;
                let no_case1 = !subject1.loosely_equals(&Val::from(1)) && !subject1.loosely_equals(&Val::from(2));
                if !matched1 && subject1.loosely_equals(&Val::from(1)) {
                    matched1 = true;
                }
                if matched1 {
                    ctx.lines_as("Picture Manager", args!["You have canceled your request."])?;
                    ctx.close_window()?;
                    return Err(Stop::End);
                }
                if !matched1 && subject1.loosely_equals(&Val::from(2)) {
                    matched1 = true;
                }
                if matched1 {
                    ctx.lines_as("Picture Manager", args!["Picture rewarding reseted."])?;
                    ctx.var("$@arena_picture").set(Val::from(0))?;
                    ctx.close_window()?;
                    return Err(Stop::End);
                }
            }
        }
    }
    Ok(Val::from(0))
}

pub fn picture_manager_arena(ctx: &Ctx) -> Script {
    picture_manager_arena_body(ctx, Vec::new()).map(|_| ())
}

fn live_broadcast_arena_body(ctx: &Ctx, args: Vec<Val>) -> Result<Val, Stop> {
    shared::other_gm_npcs::f_gm_npc(ctx, vec![])?;
    ctx.lines_as(
        "Live Broadcast",
        args![
            ((Val::from("Currently there are ") + ctx.call(Function::GetMapUsers, vec![Val::from("force_1-1")])?)
                + Val::from(" people in Lv 50s map.")),
            ((Val::from("Currently there are ") + ctx.call(Function::GetMapUsers, vec![Val::from("force_2-1")])?)
                + Val::from(" people in Lv 60s map.")),
            ((Val::from("Currently there are ") + ctx.call(Function::GetMapUsers, vec![Val::from("force_3-1")])?)
                + Val::from(" people in Lv 70s map.")),
            ((Val::from("Currently there are ") + ctx.call(Function::GetMapUsers, vec![Val::from("force_4-1")])?)
                + Val::from(" people in Lv 80s map.")),
            ((Val::from("Currently there are ") + ctx.call(Function::GetMapUsers, vec![Val::from("force_1-2")])?)
                + Val::from(" people in party map.")),
            ((Val::from("Currently there are ") + ctx.call(Function::GetMapUsers, vec![Val::from("arena_room")])?)
                + Val::from(" people in the waiting room."))
        ],
    )?;
    ctx.close_window()?;
    return Err(Stop::End);
}

pub fn live_broadcast_arena(ctx: &Ctx) -> Script {
    live_broadcast_arena_body(ctx, Vec::new()).map(|_| ())
}
